INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist PCIe immer schneller als SATA für SSDs?', 2, '[{"text": "Ja", "correct": true, "because": "PCIe bietet höhere Bandbreite"}, {"text": "Nein", "correct": false, "because": "SATA ist oft langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von PCIe gegenüber älteren Standards wie PCI?', 3, '[{"text": "Höhere Datenrate", "correct": true, "because": "PCIe nutzt serielle Punkt-zu-Punkt-Verbindungen"}, {"text": "Geringere Bandbreite", "correct": false, "because": "PCIe hat mehr Bandbreite"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten nutzen PCIe typischerweise?', 5, '[{"text": "Grafikkarten", "correct": true, "because": "Benötigen hohe Bandbreite"}, {"text": "SSDs", "correct": true, "because": "Nutzen NVMe über PCIe"}, {"text": "Tastaturen", "correct": false, "because": "Nutzen USB"}, {"text": "Monitore", "correct": false, "because": "Nutzen HDMI oder DisplayPort"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PCIe 5.0 verdoppelt die Bandbreite von PCIe 4.0. b) PCIe ist nicht abwärtskompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, PCIe ist abwärtskompatibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines PCIe-Steckplatzes?', 4, '[{"text": "Lane-Anzahl", "correct": false, "because": "Bestimmt Bandbreite"}, {"text": "Generation", "correct": false, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Farbe des Mainboards", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PCIe x16 immer für Grafikkarten reserviert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch für andere Karten genutzt werden"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für PCIe-Geschwindigkeit entscheidend?', 3, '[{"text": "Anzahl der Lanes", "correct": true, "because": "Mehr Lanes, höhere Bandbreite"}, {"text": "Spannungsversorgung", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Einstellung", "correct": false, "because": "Automatisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standards nutzen PCIe-Protokolle?', 5, '[{"text": "M.2", "correct": true, "because": "Für NVMe-SSDs"}, {"text": "Thunderbolt", "correct": true, "because": "Kombiniert PCIe und DisplayPort"}, {"text": "USB 2.0", "correct": false, "because": "Anderes Protokoll"}, {"text": "VGA", "correct": false, "because": "Analoge Schnittstelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PCIe 6.0 nutzt PAM4-Signalisierung. b) PCIe ersetzt USB komplett. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, USB bleibt eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine PCIe-Verbindung?', 4, '[{"text": "Kompatible Hardware", "correct": false, "because": "Erforderlich für Funktion"}, {"text": "Treiber", "correct": false, "because": "Sichern Kommunikation"}, {"text": "Externe Stromversorgung", "correct": true, "because": "Slot liefert Strom"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist PCIe ein paralleler Bus?', 2, '[{"text": "Nein", "correct": true, "because": "PCIe ist seriell"}, {"text": "Ja", "correct": false, "because": "Im Gegensatz zu PCI"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte profitieren von PCIe x16?', 4, '[{"text": "High-End-GPUs", "correct": true, "because": "Benötigen maximale Bandbreite"}, {"text": "RAID-Controller", "correct": true, "because": "Nutzen hohe Datenraten"}, {"text": "Mäuse", "correct": false, "because": "Nutzen USB"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PCIe keine Hot-Plug-Funktion hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "PCIe unterstützt Hot-Plug"}, {"text": "Ja", "correct": false, "because": "Hot-Plug ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl einer PCIe-Karte?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Sichert Funktion mit System"}, {"text": "Preis allein", "correct": false, "because": "Qualität wichtiger"}, {"text": "Manuelle Installation", "correct": false, "because": "Automatisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PCIe-Lanes beeinflussen die Bandbreite. b) PCIe benötigt immer externe Kabel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, intern genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet PCIe?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Ermöglicht schnelle Datenübertragung"}, {"text": "Abwärtskompatibilität", "correct": true, "because": "Unterstützt ältere Karten"}, {"text": "Einfache Installation", "correct": false, "because": "Treiber nötig"}, {"text": "Geringe Kosten", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei PCIe-Systemen unwichtig?', 3, '[{"text": "Lane-Konfiguration", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Mainboard-Unterstützung", "correct": false, "because": "Sichert Kompatibilität"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein PCIe-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt PCIe NVMe?', 3, '[{"text": "Ja", "correct": true, "because": "NVMe nutzt PCIe für SSDs"}, {"text": "Nein", "correct": false, "because": "NVMe basiert auf PCIe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PCIe für Netzwerkschnittstellen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. für High-Speed-NICs"}, {"text": "Nein", "correct": false, "because": "PCIe ist vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu PCIe?', 4, '[{"text": "Installation einer NVMe-SSD", "correct": true, "because": "Nutzt PCIe für Geschwindigkeit"}, {"text": "Anschluss eines Druckers", "correct": false, "because": "Nutzt USB"}, {"text": "Monitorverbindung", "correct": false, "because": "Nutzt DisplayPort"}]');
